  const sha = git(repo, "rev-parse", "HEAD");
  git(repo, "update-ref", "refs/remotes/pull/802/head", sha);
  git(repo, "checkout", "--detach", "refs/remotes/pull/802/head");
  describe(repo, "A checkout --detach refs/remotes/pull/802/head:");
