40	/**
41	 * What to say when this run has no branch at all.
42	 *
43	 * The state, not the symptom. This used to be "Cannot determine branch name; set
44	 * BRANCH env", and before that the third route below handed git's own description
45	 * of a detached HEAD -- `(HEAD detached at pull/802/head)` -- to `git push -u
46	 * origin <that>`, which answered `fatal: invalid refspec`. An agent reading a raw
47	 * git failure concludes the tool is broken; what it needs to know is that this
48	 * checkout has no branch to push, so there is nothing for these tools to publish.
49	 */
50	const NO_BRANCH_MESSAGE =
51	  "This run is on a detached checkout with no local branch, so there is no branch to push: " +
52	  "commit_and_push and create_pr cannot publish this run's work. Report the work on the issue instead.";
53	
54	/**
55	 * Whether `name` is a branch that exists locally -- `refs/heads/<name>` -- rather
56	 * than a name git merely printed.
57	 *
58	 * Asked rather than assumed, because every route below can hand back a string that
59	 * looks like a branch and is not one: `git branch --points-at HEAD` prints its own
60	 * pseudo-entry for a detached HEAD, and `BRANCH` is set by the runner from
61	 * whatever `git rev-parse --abbrev-ref HEAD` said. `git show-ref --verify` is the
62	 * check git itself uses for "is this a ref", so a name that is not one -- including
63	 * the pseudo-entry, whose parentheses are not valid in a refname -- fails here
64	 * rather than at the push.
65	 */
66	function isLocalBranch(name: string): boolean {
67	  if (!name || name === "HEAD" || name.startsWith("(")) return false;
68	  return gitRun("show-ref", "--verify", "--quiet", `refs/heads/${name}`).code === 0;
69	}
70	
71	/**
72	 * The branch this run is checked out on, however it can be determined.
73	 *
74	 * Every route answers only with a name that resolves as `refs/heads/<name>`, and
75	 * nothing resolves to the literal `HEAD`, an empty string, or git's description of
76	 * a detached HEAD. A route that cannot answer falls through to the next; when none
77	 * can, the run has no branch and says so (see `NO_BRANCH_MESSAGE`).
78	 */
79	export function resolveBranch(): string {
80	  const fromEnv = (process.env.BRANCH ?? "").trim();
81	  if (isLocalBranch(fromEnv)) return fromEnv;
82	  {
83	    const { code, stdout } = gitRun("rev-parse", "--abbrev-ref", "HEAD");
84	    const name = code === 0 ? stdout.trim() : "";
85	    if (isLocalBranch(name)) return name;
86	  }
87	  {
88	    // The case this route allows: a detached HEAD at a commit that a LOCAL branch
89	    // points at, so there is a name the work belongs on and a branch to push.
90	    //
91	    // The case it rejects, and the one a `pr` run is in: a detached HEAD at a commit
92	    // that only a remote-tracking or `refs/pull/<n>/head` ref points at. That commit
93	    // is a tip of something, but nothing local names it, so there is no branch to
94	    // push and the honest answer is the refusal below rather than a string git will
95	    // reject as a refspec.
96	    //
97	    // `git branch --points-at HEAD` lists the allowed branch -- but its first line is
98	    // git's own pseudo-entry for the detached HEAD, `(HEAD detached at
99	    // pull/802/head)`, which `--format` does not suppress and which is a description
100	    // rather than a ref. Every line is therefore checked, not just the first: a name
101	    // beginning with `(` and a name that does not resolve as `refs/heads/<name>` are
102	    // both rejected.
103	    const { code, stdout } = gitRun("branch", "--format=%(refname:short)", "--points-at=HEAD");
104	    if (code === 0) {
105	      for (const line of stdout.split("\n")) {
106	        const name = line.trim();
107	        if (isLocalBranch(name)) return name;
108	      }
109	    }
110	  }
111	  throw new Error(NO_BRANCH_MESSAGE);
